INSERT INTO rules (rule_id, section_code, rule_text, rule_type, trigger_text, condition_text, validation_text, action_text, exception_text, output_text) VALUES ('CH4-SEC4_11-R002', '4.11', 'All imported inputs
excluding wastage shall be utilised in manufacturing of export product.', 'business_rule', 'Advance Authorisation for Free of Cost and Paid Material', '4.11 Advance Authorisation for Free of Cost and Paid Material
Authorisations granted in terms of paragraph 4.19 of FTP, a specific endorsement by
Regional Authority shall be made in the condition sheet of Advance Authorisation,
disallowing remittances for material being supplied free of cost.', 'All imported inputs
excluding wastage shall be utilised in manufacturing of export product.', 'Manual review required.', 'No explicit exception found in uploaded documents.', 'DEKAI should produce a compliance decision for 4.11 - Advance Authorisation for Free of Cost and Paid Material.');
INSERT INTO conditions (section_code, condition_text) VALUES ('4.11', '4.11 Advance Authorisation for Free of Cost and Paid Material
Authorisations granted in terms of paragraph 4.19 of FTP, a specific endorsement by
Regional Authority shall be made in the condition sheet of Advance Authorisation,
disallowing remittances for material being supplied free of cost.');
INSERT INTO authorities (section_code, authority_name) VALUES ('4.11', 'Regional Authority');
INSERT INTO workflows (section_code, step_index, step_text) VALUES ('4.11', 1, 'Evaluate condition: 4.11 Advance Authorisation for Free of Cost and Paid Material
Authorisations granted in terms of paragraph 4.19 of FTP, a specific endorsement by
Regional Authority shall be made in the condition sheet of Advance Authorisation,
disallowing remittances for material being supplied free of cost.');
INSERT INTO workflows (section_code, step_index, step_text) VALUES ('4.11', 2, 'Run validation: 4.11 Advance Authorisation for Free of Cost and Paid Material
Authorisations granted in terms of paragraph 4.19 of FTP, a specific endorsement by
Regional Authority shall be made in the condition sheet of Advance Authorisation,
disallowing remittances for material being supplied free of cost.');
INSERT INTO workflows (section_code, step_index, step_text) VALUES ('4.11', 3, 'Run validation: All imported inputs
excluding wastage shall be utilised in manufacturing of export product.');
