INSERT INTO conditions (section_code, condition_text) VALUES ('4.79', '4.79 Export through Exhibitions/Export Promotion Tours/ Export of
Branded Jewellery
(a) Nominated Agencies shall produce to Customs Authorities letter in
original or its certified copy, containing Government’s approval for
holding exhibition/export of branded jewellery.');
INSERT INTO conditions (section_code, condition_text) VALUES ('4.79', 'Commissioner, customs letter in original or its
